+	s := "before"
+	p := &s
+	target := reflect.TypeOf(ptcStrPtr(nil))
+	q1 := reflect.ValueOf(p).Convert(target).Interface().(ptcStrPtr)
+	q2 := reflect.ValueOf(p).Convert(target).Interface().(ptcStrPtr)
+	if got := reflect.TypeOf(q1); got != target {
