+		t.Errorf("repeated reflective conversions are unequal")
+	}
+	if back := reflect.ValueOf(q1).Convert(reflect.TypeOf(p)).Interface().(*string); back != p {
+		t.Errorf("reflective round trip lost pointer identity")
+	}
+	*q1 = "after"
+	if s != "after" {
